    int p = (int)sqrt(MAXN);
    for (int i = 3; i <= p; i += 2) {
        if (!flag[i]) {
            for (int j = i * i; j <= MAXN; j += 2 * i) {
                flag[j] = true;
            }
        }
    }
    primes.push_back(2);
    for (int i = 3; i <= MAXN; i += 2) {
        if (!flag[i]) {
            primes.push_back(i);
        }
    }
}

