    while (scanf("%lld", &n) != EOF) {
        if (n == 1 || n == 0) {
            count = 0;
        } else {
            count = 1;
            for (int i = 0; primes[i] <= n; ++i) {
                if (primes[i] >= 3 && primes[i] <= n) {
